 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/8.14.4/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    id("org.springframework.boot") version "4.0.0"
    id("io.spring.dependency-management") version "1.1.7"
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Spring Boot Web (includes embedded Tomcat, Spring MVC, Jackson)
    implementation("org.springframework.boot:spring-boot-starter-web")

    // Spring Data JPA + Hibernate
    implementation("org.springframework.boot:spring-boot-starter-data-jpa")

    // Lombok (compile-time annotation processing)
    compileOnly("org.projectlombok:lombok")
    annotationProcessor("org.projectlombok:lombok")

    // H2 in-memory database (used for tests / local dev)
    runtimeOnly("com.h2database:h2")

    // Spring Boot Test (JUnit 5, MockMvc, AssertJ, Hamcrest, etc.)
    testImplementation("org.springframework.boot:spring-boot-starter-test")

    // Spring Boot 4.x WebMVC test support (@AutoConfigureMockMvc, MockMvc slices)
    testImplementation("org.springframework.boot:spring-boot-starter-webmvc-test")

    // Lombok for test sources
    testCompileOnly("org.projectlombok:lombok")
    testAnnotationProcessor("org.projectlombok:lombok")

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    // Define the main class for the application.
    mainClass = "org.example.Application"
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}
